def is_perfect_mountain(s):
    n = len(s)
    if n < 3:
        return False

    i = 1
    while i < n - 1 and s[i] > s[i - 1]:
        i += 1

    peak = i - 1

    if peak == 0 or peak == n - 1 or s[peak] <= s[peak - 1] or s[peak] <= s[peak + 1]:
        return False

    while i < n and s[i] < s[i - 1]:
        i += 1

    return i == n

def main():
    t = int(input())
    for _ in range(t):
        sequence = input().strip()
        print("YES" if is_perfect_mountain(sequence) else "NO")

if __name__ == "__main__":
    main()

