import sys

def is_mountain(s):
    n = len(s)
    if n < 3:
        return False
    i = 0
    while i + 1 < n and s[i] < s[i+1]:
        i += 1
    if i == 0 or i == n-1:
        return False
    while i + 1 < n and s[i] > s[i+1]:
        i += 1
    return i == n-1

