    dinh=-1
    for x in range(1,n-1):
        if s[x-1]<s[x]>s[x+1]:
            dinh=x
            break
    if dinh==-1 or dinh==0 or dinh==n-1:
        return False
#kiểm tra trước đỉnh
    for i in range(dinh):
        if s[i]>=s[i+1]:
            return False
#kiểm tra sau đỉnh
    for i in range(dinh,n-1):
        if s[i]<=s[i+1]:
           return False
    return True
