def is_perfect_mountain(s):
    n = len(s)
    if n < 3:
        return False
    i = 1
    while i < n and s[i] > s[i-1]:
        i += 1
    if i == 1 or i == n:
        return False
    while i < n and s[i] < s[i-1]:
        i += 1
    return i == n
t = int(input())
for _ in range(t):
    s = input().strip()
    print("YES" if is_perfect_mountain(s) else "NO")
